static bool TryReadScore(ReadOnlySpan<char> line, out int userId, out int score)
{
    userId = 0;
    score = 0;
    var comma = line.IndexOf(',');
    if (comma < 0) return false;
    if (!int.TryParse(line[..comma], out userId)) return false;
    var rest = line[(comma + 1)..];
    var comma2 = rest.IndexOf(',');
    var scoreCell = comma2 < 0 ? rest : rest[..comma2];
    return int.TryParse(scoreCell, out score);
}

