static string FormatAttemptKey(int tenantId, int attemptId, Span<char> scratch)
{
    if (!scratch.TryWrite($"attempt:{tenantId}:{attemptId}", out var written))
    {
        return $"attempt:{tenantId}:{attemptId}";
    }
    return new string(scratch[..written]);
}
